this.config = {
  "autostart": false,
  "tcf": true,
  "publisher": false,
  "PublisherID": "1cf274ee-ba43-4a1a-adfe-706d4943a049",
  "scripts": ["audiencerate","pubmatic","ttd","zeotap","onetag","adform"],
  "callback": async function cb(data) {
  // "this" is __tnc
    // Fire weborama sync only for logged users
    let CVs = this.sent[data.eid].data.Cv || [];

    let WeboramaIABVendorID = 284;
    let isLogged = (CVs||[]).find(i=>{
        return i.N=='logged' && i.V.toString()=='1';
    });

    if (isLogged) {
        let tcData = await this.getTCF(WeboramaIABVendorID);
        if ((tcData.vendors||[]).length){
            if (!this.scripts.weborama_sync) {
                await this.loadScript('https://js.tncid.app/02_weborama_sync.js', 'tnc_weborama_sync');
            }
            return this.scripts.weborama_sync();
        }
    }
    return null;
},
  "prepare": async function prepare() {
  try {
        this.scripts.pubmatic.once = true;
    } catch(err){
        this.log(err);
    }

    try {
        let invalidValues = [
            'undefined',
            'null',
            '__rcs_ppid__',
            ''
        ];
        // Aggiungo gli md5 delle stringhe qui sopra come valori non validi
        invalidValues = invalidValues.concat(invalidValues.map(i=>this.md5(i)));

        /* Grab email?
        this.setConfig({
            e: JSON.parse(this.getCookie('rcsLogin')||'""').split('|').find(i=>i.match(/^[a-z0-9\_\-\.]+@([a-z0-9\_\-]+\.){1,}[a-z]{2,}$/img))
        });
        */

        var cvIdx = this.customVariables.findIndex(cv=>(cv.N||'').toUpperCase()=='PPID' && invalidValues.includes((cv.V||'').toLowerCase()));
        while (cvIdx>-1) {
            this.customVariables.splice(cvIdx, 1);
            cvIdx = this.customVariables.findIndex(cv=>(cv.N||'').toUpperCase()=='PPID' && invalidValues.includes((cv.V||'').toLowerCase()));
        };

        let PermutiveIDCV = this.CustomVariable('permutive_id');
        let PermutiveID = this.getCookie('permutive-id');
        if (!PermutiveIDCV && PermutiveID) {
            this.CustomVariable = { N: 'permutive_id', T: 'string', V: PermutiveID };
        }
        let isLogged = this.CustomVariable('logged');
        let rcsLogin = this.getCookie('rcsLogin');
        if (!isLogged) {
            this.CustomVariable = { N: 'logged', T: 'string', V: +!!rcsLogin };
        } 

        if (this.mainConf.ex && invalidValues.includes((this.mainConf.ex||'').toLowerCase())) {
            this.mainConf.ex='';
        }
        if (this.mainConf.ex) {
            this.setPPID(this.mainConf.ex+'');
            // this.CustomVariable = { N: 'PPID', T: 'string', V: this.mainConf.ex };
            this.mainConf.ex='';
        }

        // Get page title
        let pt = (window.document.getElementsByTagName('title')[0] || {}).innerText || '';
        if (pt) this.CustomVariable = { N: 'PageTitle', T: 'string', V: pt };
    } catch(err){
        console.log(err);
    }

    return true;
}
}
